function t(){return UI[state.lang||"en"]}function L(en,fr){return state.lang==="fr"?fr:en}function esc(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}function save(){localStorage.setItem(KEY,JSON.stringify(state))}function load(){try{const r=localStorage.getItem(KEY);if(r)state={...state,...JSON.parse(r)}}catch(_){}}function clear(){localStorage.removeItem(KEY)}
function updateHeader(){langButtons.forEach(b=>b.classList.toggle("active",b.dataset.lang===state.lang));const p=document.getElementById("privacyLink");p.textContent=t().privacy;p.href="privacy.php?lang="+(state.lang||"en")}function setLang(l){state.lang=l==="fr"?"fr":"en";document.documentElement.lang=state.lang;save();updateHeader();render()}langButtons.forEach(b=>b.addEventListener("click",()=>setLang(b.dataset.lang)));
async function api(a,p={}){const c=new AbortController(),tm=setTimeout(()=>c.abort(),8000);try{const r=await fetch("api.php?action="+encodeURIComponent(a),{method:"POST",headers:{"Content-Type":"application/json","Accept":"application/json"},credentials:"same-origin",body:JSON.stringify(p),signal:c.signal});const d=await r.json().catch(()=>({ok:false,error:"Invalid server response."}));if(!r.ok||!d.ok)throw new Error(d.error||"Server error.");return d}finally{clearTimeout(tm)}}
function page(h){root.innerHTML='<section class="card">'+h+'</section>'}function actions(h){return '<div class="actions">'+h+'</div>'}function tx(q){return q[state.lang]||q.en}function aid(){const d=state.answers.recent_difficulty;if(d==="beginning")return"adaptive_start";if(["staying","time","switching"].includes(d))return"adaptive_focus";if(["deciding","returning","remembering"].includes(d))return"adaptive_planning";return null}function core(){const a=aid();return DATA.core.filter(q=>!q.adaptive||q.id===a)}function findq(id){for(const q of DATA.core)if(q.id===id)return q;for(const m of Object.values(DATA.modules))for(const q of m.questions)if(q.id===id)return q;return null}function options(q){let o=(tx(q).options||[]);if(q.type==="dynamic_one"){const src=findq(q.from),allowed=state.answers[q.from]||[];o=(tx(src).options||[]).filter(x=>allowed.includes(x[0])).map(x=>[x[0],x[1]])}return o}
function normal(q){const cur=state.answers[q.id],multi=["multi2","multi3","multi5","exact5"].includes(q.type),type=multi?"checkbox":"radio";return '<div class="options">'+options(q).map(o=>{const chk=Array.isArray(cur)?cur.includes(o[0]):cur===o[0];return `<label class="option"><input ${chk?"checked":""} type="${type}" name="q_${esc(q.id)}" value="${esc(o[0])}"><span>${esc(o[1])}</span></label>`}).join("")+'</div>'}function visual(q){const cur=state.answers[q.id];return '<div class="visuals">'+options(q).map(o=>`<label class="vcard"><div><input ${cur===o[0]?"checked":""} type="radio" name="q_${esc(q.id)}" value="${esc(o[0])}"> <strong>${esc(o[1])}</strong></div><div class="mock">${esc(o[3]||"")}</div><div class="small">${esc(o[2]||"")}</div></label>`).join("")+'</div>'}
function collect(q){if(["multi2","multi3","multi5","exact5"].includes(q.type))return [...root.querySelectorAll(`input[name="q_${q.id}"]:checked`)].map(x=>x.value);return root.querySelector(`input[name="q_${q.id}"]:checked`)?.value||""}function valid(q,a){if(q.type==="exact5")return Array.isArray(a)&&a.length===5;if(q.type==="multi2")return Array.isArray(a)&&a.length>=1&&a.length<=2;if(q.type==="multi3")return Array.isArray(a)&&a.length>=1&&a.length<=3;if(q.type==="multi5")return Array.isArray(a)&&a.length>=1&&a.length<=5;return !!a}function helper(q){if(q.type==="exact5")return t().exact5;if(q.type==="multi2")return t().up2;if(q.type==="multi3")return t().up3;if(q.type==="multi5")return t().up5;return tx(q).help||""}async function store(q,a){state.answers[q.id]=a;save();await api("save",{token:state.token,question_id:q.id,answer:a,current_step:state.current})}
function language(){page(`<p class="eyebrow">Le Potager Lab</p><h1>${esc(UI.fr.languageTitle)} / ${esc(UI.en.languageTitle)}</h1><p class="lead">${esc(UI.fr.languageLead)}<br>${esc(UI.en.languageLead)}</p><div class="grid"><button class="module primary" id="fr">🇫🇷 Français</button><button class="module primary" id="en">🇬🇧 English</button></div>`);document.getElementById("fr").onclick=()=>{state.lang="fr";state.current="welcome";save();updateHeader();render()};document.getElementById("en").onclick=()=>{state.lang="en";state.current="welcome";save();updateHeader();render()}}
function welcome(){page(`<p class="eyebrow">${esc(t().welcomeEyebrow)}</p><h1>${esc(t().welcomeTitle)}</h1><p class="lead">${esc(t().welcomeLead)}</p><div class="soft"><strong>${esc(t().time)}</strong><br>${esc(t().time2)}<br><br><strong>${esc(t().resumeIntro)}</strong></div><div class="notice">${esc(t().noHealth)}</div>${actions(`<button class="primary" id="go">${esc(t().continue)}</button><a class="btn secondary" href="privacy.php?lang=${state.lang}">${esc(t().privacy)}</a>`)}`);document.getElementById("go").onclick=()=>{state.current="readiness";save();render()}}
function readiness(){page(`<p class="eyebrow">${esc(t().readyEyebrow)}</p><h2>${esc(t().readyTitle)}</h2><p class="lead">${esc(t().readyLead)}</p><div class="soft">${esc(t().readySoft)}</div>${actions(`<button class="secondary" id="later">${esc(t().later)}</button><button class="primary" id="ready">${esc(t().ready)}</button>`)}`);document.getElementById("later").onclick=()=>{state.current="later";save();render()};document.getElementById("ready").onclick=()=>{state.current="age";save();render()}}
