function age(){page(`<p class="eyebrow">${esc(t().ageEyebrow)}</p><h2>${esc(t().ageTitle)}</h2><p class="lead">${esc(t().ageLead)}</p><div class="options"><label class="option"><input type="radio" name="age" value="adult"><span>${esc(t().adult)}</span></label><label class="option"><input type="radio" name="age" value="minor"><span>${esc(t().minor)}</span></label><label class="option"><input type="radio" name="age" value="under13"><span>${esc(t().under13)}</span></label></div><div id="err"></div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><button class="primary" id="next">${esc(t().continue)}</button>`)}`);document.getElementById("back").onclick=()=>{state.current="readiness";save();render()};document.getElementById("next").onclick=()=>{const a=root.querySelector('input[name="age"]:checked')?.value;if(!a){document.getElementById("err").innerHTML=`<div class="notice error">${esc(t().choose)}</div>`;return}state.ageRoute=a;state.current=a==="adult"?"adult_consent":a==="minor"?"minor_region":"under13";save();render()}}function under13(){page(`<h2>${esc(t().underTitle)}</h2><p class="lead">${esc(t().underLead)}</p><div class="notice">${esc(t().underNote)}</div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><a class="btn quiet" href="https://www.lepotager.org/">${esc(t().leave)}</a>`)}`);document.getElementById("back").onclick=()=>{state.current="age";save();render()}}
function adultConsent(){page(`<h2>${esc(t().consentTitle)}</h2><p class="lead">${esc(t().consentLead)}</p><label class="consent"><input id="c1" type="checkbox"><span>${esc(t().c1)}</span></label><label class="consent"><input id="c2" type="checkbox"><span>${esc(t().c2)}</span></label><label class="consent"><input id="c3" type="checkbox"><span>${esc(t().c3)} <a href="privacy.php?lang=${state.lang}" target="_blank">${esc(t().privacy)}</a></span></label><div id="err"></div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><button class="primary" id="start">${esc(t().agree)}</button>`)}`);document.getElementById("back").onclick=()=>{state.current="age";save();render()};document.getElementById("start").onclick=async()=>{if(!["c1","c2","c3"].every(id=>document.getElementById(id).checked)){document.getElementById("err").innerHTML=`<div class="notice error">${esc(t().confirmAll)}</div>`;return}try{const d=await api("start_participant",{participant_agreement:true,cohort:"adult"});state.token=d.token;state.current="recent_difficulty";save();render()}catch(e){document.getElementById("err").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}function minorRegion(){
 const options=[["france","France"],["belgium",L("Belgium","Belgique")],["luxembourg","Luxembourg"],["switzerland",L("Switzerland","Suisse")],["us",L("United States","États-Unis")],["canada","Canada"],["other",L("Another country","Un autre pays")]];
 page(`<p class="eyebrow">${esc(L("Ages 13–17","13–17 ans"))}</p><h2>${esc(L("Where do you currently live?","Dans quel pays vivez-vous actuellement ?"))}</h2><p class="lead">${esc(L("This is used only to choose the appropriate privacy route. Your exact country choice is not stored as a questionnaire answer.","Ce choix sert uniquement à appliquer le parcours de confidentialité approprié. Votre pays exact n’est pas enregistré comme réponse au questionnaire."))}</p><div class="options">${options.map(o=>`<label class="option"><input type="radio" name="minor_country" value="${esc(o[0])}"><span>${esc(o[1])}</span></label>`).join("")}</div><div id="err"></div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><button class="primary" id="next">${esc(t().continue)}</button>`)}`);
 document.getElementById("back").onclick=()=>{state.current="age";save();render()};
 document.getElementById("next").onclick=()=>{const c=root.querySelector('input[name="minor_country"]:checked')?.value;if(!c){document.getElementById("err").innerHTML=`<div class="notice error">${esc(t().choose)}</div>`;return}state.minorCountry=c;if(["france","belgium","luxembourg"].includes(c)){state.minorRoute="eu_supported";state.current="minor_assent"}else if(c==="us"){state.minorRoute="us_13_17";state.current="minor_assent"}else if(c==="canada"){state.current="minor_canada"}else if(c==="switzerland"){state.current="minor_swiss_age"}else{state.current="minor_unavailable"}save();render()}
}
