 page(`<p class="eyebrow">${esc(L("Canada · ages 13–17","Canada · 13–17 ans"))}</p><h2>${esc(L("Do you currently live in Quebec?","Vivez-vous actuellement au Québec ?"))}</h2><p class="lead">${esc(L("The privacy rule for under-14 participants is different in Quebec. This choice is used only for routing.","La règle de confidentialité concernant les moins de 14 ans est différente au Québec. Ce choix sert uniquement au routage."))}</p><div class="options"><label class="option"><input type="radio" name="ca" value="qc"><span>Québec / Quebec</span></label><label class="option"><input type="radio" name="ca" value="other"><span>${esc(L("Another province or territory","Une autre province ou un autre territoire"))}</span></label></div><div id="err"></div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><button class="primary" id="next">${esc(t().continue)}</button>`)}`);
 document.getElementById("back").onclick=()=>{state.current="minor_region";save();render()};
