 document.getElementById("back").onclick=()=>{state.current="minor_canada";save();render()};
 document.getElementById("next").onclick=()=>{const a=root.querySelector('input[name="qca"]:checked')?.value;if(!a){document.getElementById("err").innerHTML=`<div class="notice error">${esc(t().choose)}</div>`;return}if(a==="14plus"){state.minorRoute="ca_qc_14_17";state.current="minor_assent"}else state.current="minor_unavailable_qc13";save();render()}
