function minorAssent(){
 const legal=state.minorRoute==="eu_supported"
  ?L("For this supported EU route, the processing is based on the controller’s legitimate interest in minimal, non-medical product research — not on your consent as the GDPR legal basis. You still freely choose whether to participate.","Pour ce parcours UE pris en charge, le traitement repose sur l’intérêt légitime du responsable à mener une recherche produit minimale et non médicale — et non sur votre consentement comme base juridique RGPD. Vous restez entièrement libre de participer ou non.")
  :L("The privacy notice explains the rule used for your region. We do not ask for a parent or guardian email in this route.","La notice de confidentialité explique la règle appliquée à votre région. Nous ne demandons pas l’e-mail d’un parent ou responsable dans ce parcours.");
 page(`<p class="eyebrow">${esc(L("For ages 13–17","Pour les 13–17 ans"))}</p><h2>${esc(L("Your choice matters","Votre choix compte"))}</h2><p class="lead">${esc(L("This is product research, not a medical or diagnostic questionnaire. It does not ask whether you have ADHD, your diagnosis, medication, exact age, name, school, workplace or participant email.","Il s’agit de recherche produit, pas d’un questionnaire médical ou diagnostique. Il ne demande pas si vous avez un TDAH, ni diagnostic, traitement, âge exact, nom, établissement scolaire, lieu de travail ou e-mail du participant."))}</p><div class="soft">${esc(legal)}</div><label class="consent"><input id="assent" type="checkbox"><span>${esc(L("I understand what this questionnaire collects and I choose to take part. I know I can stop at any time and can delete my saved response from this device while its private session token is still here.","Je comprends ce que ce questionnaire collecte et je choisis d’y participer. Je sais que je peux arrêter à tout moment et supprimer ma réponse enregistrée depuis cet appareil tant que son jeton privé de session y est encore disponible."))}</span></label><label class="consent"><input id="privacyok" type="checkbox"><span>${esc(L("I have read the privacy information.","J’ai lu les informations de confidentialité."))} <a href="privacy.php?lang=${state.lang}" target="_blank">${esc(t().privacy)}</a></span></label><div id="err"></div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><button class="primary" id="start">${esc(L("Start questionnaire","Commencer le questionnaire"))}</button>`)}`);
 document.getElementById("back").onclick=()=>{state.current="minor_region";save();render()};
 document.getElementById("start").onclick=async()=>{if(!document.getElementById("assent").checked||!document.getElementById("privacyok").checked){document.getElementById("err").innerHTML=`<div class="notice error">${esc(L("Please confirm both points.","Merci de confirmer les deux points."))}</div>`;return}try{const d=await api("start_participant",{participant_agreement:true,cohort:"minor",minor_route:state.minorRoute});state.token=d.token;state.minorCountry=null;state.minorRoute=null;state.guardianPollToken=null;state.current="recent_difficulty";save();render()}catch(e){document.getElementById("err").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
}
function deleteCurrentResponse(){
 if(!state.token){clear();location.reload();return}
 if(!confirm(L("Delete this questionnaire response permanently? This cannot be undone.","Supprimer définitivement cette réponse au questionnaire ? Cette action est irréversible.")))return;
 api("delete",{token:state.token}).then(()=>{clear();location.reload()}).catch(e=>alert(e.message))
}
function nextCore(q){const c=core(),i=c.findIndex(x=>x.id===q.id);return i>=0&&i<c.length-1?c[i+1].id:"core_review"}function modFor(id){for(const [k,m] of Object.entries(DATA.modules))if(m.questions.some(q=>q.id===id))return[k,m];return null}
function renderQuestion(q){const z=tx(q),c=core(),i=c.findIndex(x=>x.id===q.id),isCore=i>=0,prog=isCore?`<p class="small">${esc(t().required)} · ${i+1}/${c.length}</p><div class="progress"><span style="width:${((i+1)/c.length)*100}%"></span></div>`:"";page(`${prog}<p class="eyebrow">${esc(z.eyebrow|| (isCore?t().required:t().optional))}</p><h2>${esc(z.title)}</h2>${helper(q)?`<p class="small">${esc(helper(q))}</p>`:""}${q.type==="visual"?visual(q):normal(q)}<div id="err"></div>${actions(`<button class="secondary" id="pause">${esc(t().pause)}</button><button class="primary" id="next">${esc(t().continue)}</button>`)}`);document.getElementById("pause").onclick=renderPause;document.getElementById("next").onclick=async()=>{const a=collect(q);if(!valid(q,a)){document.getElementById("err").innerHTML=`<div class="notice error">${esc(q.type==="exact5"?t().exact5:t().chooseAnswer)}</div>`;return}try{await store(q,a);if(isCore)state.current=nextCore(q);else{const [k,m]=modFor(q.id),j=m.questions.findIndex(x=>x.id===q.id);state.current=j===m.questions.length-1?"optional_hub":m.questions[j+1].id;if(state.current==="optional_hub")state.module=null}save();render()}catch(e){document.getElementById("err").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
function renderPause(){page(`<h2>${esc(t().savedTitle)}</h2><p class="lead">${esc(t().savedLead)}</p><div class="notice small">${esc(L("If you want to withdraw this saved response instead, you can delete it from this device while the private session token is still stored here.","Si vous souhaitez retirer cette réponse enregistrée, vous pouvez la supprimer depuis cet appareil tant que le jeton privé de session y est encore stocké."))}</div>${actions(`<button class="primary" id="resume">${esc(t().continueNow)}</button><a class="btn secondary" href="https://www.lepotager.org/">${esc(t().leave)}</a><button class="quiet" id="delete">${esc(L("Delete my saved response","Supprimer ma réponse enregistrée"))}</button>`)}`);document.getElementById("resume").onclick=render;document.getElementById("delete").onclick=deleteCurrentResponse}function coreReview(){page(`<p class="eyebrow">${esc(t().coreDoneEyebrow)}</p><h2>${esc(t().coreDoneTitle)}</h2><p class="lead">${esc(t().coreDoneLead)}</p><div class="soft">${esc(t().coreDoneSoft)}</div><div id="err"></div>${actions(`<button class="secondary" id="back">${esc(t().back)}</button><button class="primary" id="submit">${esc(t().submitCore)}</button>`)}`);document.getElementById("back").onclick=()=>{const c=core();state.current=c[c.length-1].id;save();render()};document.getElementById("submit").onclick=async()=>{try{await api("submit_core",{token:state.token});state.coreSubmitted=true;state.current="optional_hub";save();render()}catch(e){document.getElementById("err").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
function mtitle(m){return state.lang==="fr"?m.fr_title:m.en_title}function mprog(m){return m.questions.filter(q=>state.answers[q.id]!==undefined).length}function optionalHub(){const d=state.answers.recent_difficulty;const rec=d==="beginning"?"tools":(["staying","time","switching"].includes(d)?"timer":(["deciding","returning","remembering"].includes(d)?"routines":null));const cards=Object.entries(DATA.modules).map(([k,m])=>{const n=mprog(m),done=n===m.questions.length;return `<article class="module ${done?"done":""}"><div><span class="badge">${done?esc(t().complete):(k===rec?esc(t().recommended):esc(t().opt))}</span><h3>${esc(mtitle(m))}</h3><p class="small">${n}/${m.questions.length}</p></div><button class="${done?"secondary":"primary"} open" data-key="${esc(k)}">${esc(done?t().review:t().explore)}</button></article>`}).join("");page(`<p class="eyebrow">${esc(t().hubEyebrow)}</p><h2>${esc(t().hubTitle)}</h2><p class="lead">${esc(t().hubLead)}</p><div class="grid">${cards}</div><div class="notice">${esc(t().hubNote)}</div><div id="err"></div>${actions(`<button class="secondary" id="pause">${esc(t().saveReturn)}</button><button class="primary" id="finish">${esc(t().finish)}</button>`)}`);root.querySelectorAll(".open").forEach(b=>b.onclick=()=>{const k=b.dataset.key,m=DATA.modules[k];state.module=k;state.current=m.questions.find(q=>state.answers[q.id]===undefined)?.id||m.questions[0].id;save();render()});document.getElementById("pause").onclick=renderPause;document.getElementById("finish").onclick=async()=>{try{await api("finish",{token:state.token});state.completed=true;state.current="done";save();render()}catch(e){document.getElementById("err").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
function done(){page(`<p class="eyebrow">${esc(t().doneEyebrow)}</p><h2>${esc(t().doneTitle)}</h2><p class="lead">${esc(t().doneLead)}</p><div class="notice small">${esc(L("This device still holds the private token for this response. You may delete the submitted response now if you change your mind.","Cet appareil possède encore le jeton privé de cette réponse. Vous pouvez supprimer la réponse envoyée maintenant si vous changez d’avis."))}</div>${actions(`<a class="btn primary" href="results.php?lang=${state.lang}">${esc(t().results)}</a><button class="secondary" id="new">${esc(t().newSession)}</button><button class="quiet" id="delete">${esc(L("Delete my response","Supprimer ma réponse"))}</button>`)}`);document.getElementById("new").onclick=()=>{clear();location.reload()};document.getElementById("delete").onclick=deleteCurrentResponse}async function resume(){if(!state.token)return;try{const d=await api("resume",{token:state.token});state.answers=d.answers||state.answers;state.coreSubmitted=["core_submitted","completed"].includes(d.session.status);state.completed=d.session.status==="completed";if(state.completed)state.current="done";else if(d.session.current_step&&(findq(d.session.current_step)||["optional_hub","core_review"].includes(d.session.current_step)))state.current=d.session.current_step;else if(!findq(state.current))state.current="recent_difficulty";save()}catch(_){}}
function render(){if(!state.lang)return language();document.documentElement.lang=state.lang;updateHeader();if(state.completed||state.current==="done")return done();const q=findq(state.current);if(q)return renderQuestion(q);const routes={language,welcome,readiness,later,age,under13,adult_consent:adultConsent,minor_region:minorRegion,minor_canada:minorCanada,minor_qc_age:minorQcAge,minor_swiss_age:minorSwissAge,minor_unavailable:minorUnavailable,minor_unavailable_qc13:minorUnavailableQc13,minor_unavailable_ch13:minorUnavailableCh13,minor_assent:minorAssent,core_review:coreReview,optional_hub:optionalHub};(routes[state.current]||welcome)()}
load();
const qp=new URLSearchParams(location.search).get("lang");
if(!state.lang){
  if(qp==="fr"||qp==="en"){
    state.lang=qp;
  }else{
    const langs=(Array.isArray(navigator.languages)&&navigator.languages.length?navigator.languages:[navigator.language||"en"])
      .map(x=>String(x||"").toLowerCase());
    const supported=langs.find(x=>x.startsWith("fr")||x.startsWith("en"));
    state.lang=supported&&supported.startsWith("fr")?"fr":"en";
  }
  if(state.current==="language")state.current="welcome";
  save();
}
document.documentElement.lang=state.lang;
updateHeader();
render();
resume().then(render);
})();